from __future__ import annotations

import json
import os
import subprocess
import sys
import time
import threading
from pathlib import Path
from typing import Any

from mt5_mac.types import (
    MqlTick, MqlRates, MqlAccountInfo, MqlSymbolInfo,
    MqlTradeRequest, MqlTradeResult, MqlPosition, MqlOrder, MqlDeal,
    MqlIndicatorBuffer, INVALID_HANDLE,
)
from mt5_mac.bootstrap import ensure_environment
from mt5_mac.indicators import compute_indicator, get_buffer


MT5_APP = "/Applications/MetaTrader 5.app"
WINE_BIN = f"{MT5_APP}/Contents/SharedSupport/wine/bin/wine64"
if not os.path.exists(WINE_BIN) and os.path.exists(f"{MT5_APP}/Contents/SharedSupport/wine/bin/wine"):
    WINE_BIN = f"{MT5_APP}/Contents/SharedSupport/wine/bin/wine"
DEFAULT_WINEPREFIX = os.path.expanduser(
    "~/Library/Application Support/net.metaquotes.wine.metatrader5")
DEFAULT_PYTHON = "C:\\Python39\\python.exe"
DEFAULT_TERMINAL = r"C:\Program Files\MetaTrader 5\terminal64.exe"

AGENT_PATH = os.path.abspath(os.path.join(os.path.dirname(__file__), "agent.py"))
WINE_AGENT_PATH = "Z:" + AGENT_PATH.replace("/", "\\")


class MT5BackendError(Exception):
    pass


class MT5Backend:
    """Connects to MetaTrader 5 on macOS via the bundled Wine in MT5.app."""
    def __init__(
        self,
        wine_bin: str = "",
        wineprefix: str = "",
        python_path: str = "",
        terminal_path: str = "",
        quiet: bool = False,
    ) -> None:
        self._wine_bin = wine_bin or WINE_BIN
        self._wineprefix = wineprefix or DEFAULT_WINEPREFIX
        self._python_path = python_path or DEFAULT_PYTHON
        self._terminal_path = terminal_path or DEFAULT_TERMINAL
        self._quiet = quiet
        self._proc: subprocess.Popen | None = None
        self._lock = threading.Lock()
        self._started = False
        self._bootstrapped = False
        self._indicators: dict[int, dict] = {}
        self._next_handle: int = 1

    def start(self, path: str | None = None) -> bool:
        if not self._bootstrapped:
            ensure_environment(
                wine_bin=self._wine_bin,
                wineprefix=self._wineprefix,
                python_path=self._python_path,
                verbose=not self._quiet,
            )
            self._bootstrapped = True

        cmd = [self._wine_bin, self._python_path, WINE_AGENT_PATH]
        env = {
            **os.environ,
            "WINEPREFIX": self._wineprefix,
            "MT5_TERMINAL_PATH": path or self._terminal_path,
        }
        try:
            self._proc = subprocess.Popen(
                cmd,
                stdin=subprocess.PIPE,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                bufsize=1,
                env=env,
            )
        except FileNotFoundError:
            raise MT5BackendError(
                f"Wine binary not found at {self._wine_bin}. "
                "Is MetaTrader 5.app installed?"
            )

        init_cmd = {"action": "initialize"}
        if path:
            init_cmd["path"] = path
        result = self._send(init_cmd)
        if result and result.get("success"):
            self._started = True
            return True
        if result:
            print(f"[mt5_mac] Wine MT5 initialize failed: error={result.get('error')}, path={result.get('terminal_path')}")
        else:
            print("[mt5_mac] Wine MT5 agent did not respond or process terminated.")
        return False

    def stop(self) -> None:
        self._started = False
        for handle in list(self._indicators.keys()):
            try:
                self.indicator_deinit(handle)
            except Exception:
                pass
        self._indicators.clear()
        if self._proc and self._proc.poll() is None:
            try:
                self._send({"action": "shutdown"})
            except Exception:
                pass
            self._proc.terminate()
            self._proc = None

    @property
    def connected(self) -> bool:
        return self._started

    def login(self, login: str, password: str, server: str = "") -> bool:
        result = self._send({
            "action": "login",
            "login": login,
            "password": password,
            "server": server,
        })
        return bool(result and result.get("success"))

    def account_info(self) -> MqlAccountInfo | None:
        result = self._send({"action": "account_info"})
        if result:
            return MqlAccountInfo(**{k: result.get(k) for k in MqlAccountInfo._fields})
        return None

    def symbols_get(self, symbol: str | None = None) -> tuple[MqlSymbolInfo, ...] | None:
        params = {}
        if symbol is not None:
            params["symbol"] = symbol
        result = self._send({"action": "symbols_get", **params})
        if result and "symbols" in result:
            return tuple(
                MqlSymbolInfo(**{k: s.get(k) for k in MqlSymbolInfo._fields})
                for s in result["symbols"]
            )
        return None

    def symbol_info(self, symbol: str) -> MqlSymbolInfo | None:
        result = self._send({"action": "symbol_info", "symbol": symbol})
        if result:
            return MqlSymbolInfo(**{k: result.get(k) for k in MqlSymbolInfo._fields})
        return None

    def symbol_info_tick(self, symbol: str) -> MqlTick | None:
        result = self._send({"action": "tick_info", "symbol": symbol})
        if result:
            return MqlTick(**{k: result.get(k) for k in MqlTick._fields})
        return None

    def symbol_select(self, symbol: str, enable: bool = True) -> bool:
        result = self._send({"action": "symbol_select", "symbol": symbol, "enable": enable})
        return bool(result and result.get("success"))

    def copy_rates_from_pos(
        self, symbol: str, timeframe: int, start_pos: int, count: int,
    ) -> tuple[MqlRates, ...] | None:
        result = self._send({
            "action": "rates_get",
            "symbol": symbol,
            "timeframe": timeframe,
            "start_pos": start_pos,
            "count": count,
        })
        if result and "rates" in result and result["rates"] is not None:
            return tuple(
                MqlRates(**{k: r.get(k) for k in MqlRates._fields})
                for r in result["rates"]
            )
        return None

    def copy_rates_from(
        self, symbol: str, timeframe: int, date_from: int, count: int,
    ) -> tuple[MqlRates, ...] | None:
        result = self._send({
            "action": "copy_rates_from",
            "symbol": symbol,
            "timeframe": timeframe,
            "date_from": date_from,
            "count": count,
        })
        if result and "rates" in result and result["rates"] is not None:
            return tuple(
                MqlRates(**{k: r.get(k) for k in MqlRates._fields})
                for r in result["rates"]
            )
        return None

    def copy_rates_range(
        self, symbol: str, timeframe: int, date_from: int, date_to: int,
    ) -> tuple[MqlRates, ...] | None:
        result = self._send({
            "action": "copy_rates_range",
            "symbol": symbol,
            "timeframe": timeframe,
            "date_from": date_from,
            "date_to": date_to,
        })
        if result and "rates" in result and result["rates"] is not None:
            return tuple(
                MqlRates(**{k: r.get(k) for k in MqlRates._fields})
                for r in result["rates"]
            )
        return None

    def order_send(self, request: dict) -> MqlTradeResult:
        result = self._send({"action": "order_send", "request": request})
        if result:
            return MqlTradeResult(**{k: result.get(k) for k in MqlTradeResult._fields})
        return MqlTradeResult(retcode=-1)

    def positions_get(self, symbol: str = "") -> tuple[MqlPosition, ...] | None:
        result = self._send({"action": "positions_get", "symbol": symbol})
        if result and "positions" in result and result["positions"] is not None:
            return tuple(
                MqlPosition(**{k: p.get(k) for k in MqlPosition._fields})
                for p in result["positions"]
            )
        return None

    def orders_get(self, symbol: str = "") -> tuple[MqlOrder, ...] | None:
        result = self._send({"action": "orders_get", "symbol": symbol})
        if result and "orders" in result and result["orders"] is not None:
            return tuple(
                MqlOrder(**{k: p.get(k) for k in MqlOrder._fields})
                for p in result["orders"]
            )
        return None

    def history_deals_get(
        self, date_from: int = 0, date_to: int = 0,
    ) -> tuple[MqlDeal, ...] | None:
        result = self._send({
            "action": "history_deals",
            "from": date_from,
            "to": date_to,
        })
        if result and "deals" in result and result["deals"] is not None:
            return tuple(
                MqlDeal(**{k: p.get(k) for k in MqlDeal._fields})
                for p in result["deals"]
            )
        return None

    def history_orders_get(
        self, date_from: int = 0, date_to: int = 0,
    ) -> tuple[MqlOrder, ...] | None:
        result = self._send({
            "action": "history_orders",
            "from": date_from,
            "to": date_to,
        })
        if result and "orders" in result and result["orders"] is not None:
            return tuple(
                MqlOrder(**{k: p.get(k) for k in MqlOrder._fields})
                for p in result["orders"]
            )
        return None

    def indicator_init(
        self, symbol: str, timeframe: int, indicator_path: str,
        buffer_count: int = 4, params: list | None = None,
        ea_timeframe: int | None = None,
    ) -> int:
        handle = self._next_handle
        self._next_handle += 1
        self._indicators[handle] = {
            "symbol": symbol,
            "timeframe": timeframe,
            "indicator_path": indicator_path,
            "buffer_count": buffer_count,
            "ea_timeframe": ea_timeframe or timeframe,
        }
        return handle

    def indicator_read(
        self, handle: int, buffer_num: int, count: int,
    ) -> tuple[MqlIndicatorBuffer, ...] | None:
        info = self._indicators.get(handle)
        if not info:
            return None

        bar_count = max(count * 3, 100)
        result = self._send({
            "action": "rates_get",
            "symbol": info["symbol"],
            "timeframe": info["timeframe"],
            "start_pos": 0,
            "count": bar_count,
        })
        if not result or "rates" not in result or not result["rates"]:
            return None

        candles = result["rates"]
        indicator_key = info["indicator_path"].split("\\")[-1].split("/")[-1]
        computed = compute_indicator(indicator_key, candles)
        if computed is None:
            if not self._quiet:
                print(f"[mt5_mac] Indicator '{indicator_key}' not implemented. "
                      f"Only Heiken Ashi is supported currently.")
            return None

        vals = get_buffer(computed, buffer_num, count)
        if not vals:
            return None

        offset = len(computed) - len(vals)
        return tuple(
            MqlIndicatorBuffer(
                time=int(computed[offset + i]["time"]),
                value=float(vals[i]),
            )
            for i in range(len(vals))
        )

    def indicator_deinit(self, handle: int) -> bool:
        info = self._indicators.pop(handle, None)
        return info is not None

    def indicator_list(self) -> dict[int, dict]:
        return dict(self._indicators)

    def _send(self, command: dict) -> dict | None:
        if self._proc is None or self._proc.poll() is not None:
            raise MT5BackendError("Backend process is not running")

        line = json.dumps(command)
        with self._lock:
            self._proc.stdin.write(line + "\n")
            self._proc.stdin.flush()
            response = self._proc.stdout.readline()

        if not response:
            stderr_text = ""
            if self._proc.poll() is not None:
                stderr_text = self._proc.stderr.read()
            raise MT5BackendError(
                f"Empty response from backend.\n"
                f"Command: {command['action']}\n"
                f"Stderr: {stderr_text.strip()}"
            )

        try:
            return json.loads(response.strip())
        except json.JSONDecodeError as e:
            raise MT5BackendError(f"Invalid JSON from backend: {e}\nResponse: {response.strip()}")
